// ═══ Tool · save_item (write) ═══
//
// The Products screen (ProductForm) writes a saved item one of two ways: a new
// item upserts on name_key — an unsaved history row, or a soft-deleted one, is
// updated to saved_at = now with deleted_at cleared — and editing a saved item
// updates unit, unit_price and detail in place. This tool uses exactly those two
// paths, so nothing reaches a column the screen cannot write. name_key is
// generated by the table and is never written here.
//
// The price is a number the model passes; the card's money string is composed by
// the server.
import { z } from 'zod';
import { defineWriteTool, type ToolContext } from '../contract';
import { ConfirmBatchProps } from '@/lib/templates/props';
import { moneyText } from '../read';

export const SAVE_ITEM = 'save_item';

const UNITS = ['each', 'hour', 'sq ft', 'job'] as const;
type Unit = (typeof UNITS)[number];

export const SaveItemInput = z
  .object({
    name: z.string().min(1).max(120),
    unit: z.enum(UNITS).optional(),
    /** A number, never a formatted figure; the card prints the money. */
    price: z.number().finite().min(0).max(10_000_000).optional(),
    detail: z.string().max(300).optional(),
  })
  .strict();

export const SaveItemOutput = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
});

type ProductRow = {
  id: string;
  name: string;
  unit: string | null;
  unit_price: number | string | null;
  detail: string | null;
  name_key?: string | null;
  saved_at?: string | null;
  deleted_at: string | null;
};

type Resolved = {
  /** null means this proposal creates the row. */
  id: string | null;
  name: string;
  unit: Unit;
  unitPrice: number | null;
  detail: string | null;
  /** What the saved row held when the card was drawn; null for a new row. */
  old: { unit: Unit; unitPrice: number | null; detail: string | null } | null;
};

const priceOf = (row: ProductRow): number | null => {
  if (row.unit_price == null) return null;
  const n = Number(row.unit_price);
  return Number.isFinite(n) ? n : null;
};

const unitOf = (row: ProductRow): Unit =>
  (UNITS as readonly string[]).includes(row.unit ?? '') ? (row.unit as Unit) : 'each';

/** "$450.00", "$65.00/hr", "$3.25/sq ft", "$85.00/job"; "no price" when unset. */
export function priceText(unit: Unit, price: number | null): string {
  if (price == null) return 'no price';
  const suffix = unit === 'hour' ? '/hr' : unit === 'sq ft' ? '/sq ft' : unit === 'job' ? '/job' : '';
  return `${moneyText(price)}${suffix}`;
}

/** The table's own key: lower(btrim(name)). */
const nameKeyOf = (name: string): string => name.trim().toLowerCase();

async function products(ctx: ToolContext): Promise<ProductRow[]> {
  const { data, error } = await ctx.db.select<ProductRow>('products', {
    columns: '*',
    eq: { user_id: ctx.userId },
  });
  if (error) throw new Error(error.message);
  return data ?? [];
}

const rowKey = (row: ProductRow): string => nameKeyOf(row.name_key ?? row.name);

export const saveItemTool = defineWriteTool({
  name: SAVE_ITEM,
  description:
    'Propose saving ONE product or service to the saved items list, with an optional price, unit (each, hour, sq ft, job) and detail line. An item with that name that is not saved yet, or was deleted, is saved in place instead of duplicated; a saved one is updated. It saves nothing: the app shows a card and the owner confirms.',
  input: SaveItemInput,
  output: SaveItemOutput,
  type: 'write',
  risk: 'low',
  defaultTemplate: { id: 'confirm.batch', props: ConfirmBatchProps },
  prepare: async (ctx, args) => {
    const name = args.name.trim().replace(/\s+/g, ' ');
    if (!name) return { ok: false, problem: 'An item needs a name.' };

    const rows = await products(ctx);
    const found = rows.find((row) => rowKey(row) === nameKeyOf(name));
    const saved = Boolean(found && found.saved_at && !found.deleted_at);

    if (found && saved) {
      const old = { unit: unitOf(found), unitPrice: priceOf(found), detail: found.detail ?? null };
      const unit = args.unit ?? old.unit;
      const unitPrice = args.price !== undefined ? args.price : old.unitPrice;
      const detail = args.detail !== undefined ? (args.detail.trim() || null) : old.detail;

      const changes: string[] = [];
      if (unit !== old.unit) changes.push(`unit ${old.unit} to ${unit}`);
      if (unitPrice !== old.unitPrice) {
        changes.push(`price ${priceText(old.unit, old.unitPrice)} to ${priceText(unit, unitPrice)}`);
      }
      if (detail !== old.detail) changes.push('details updated');
      if (changes.length === 0) return { ok: false, problem: `${found.name} is already saved with those details.` };

      return {
        ok: true,
        resolved: { id: found.id, name: found.name, unit, unitPrice, detail, old } satisfies Resolved,
        row: {
          icon: 'inventory_2',
          summary: `Update item ${found.name}: ${changes.join(' · ')}`,
          // The price is the one figure a saved item has; the server composes it.
          amount: unitPrice == null ? '' : priceText(unit, unitPrice),
          tone: 'neutral',
        },
      };
    }

    const unit = args.unit ?? (found ? unitOf(found) : 'each');
    const unitPrice = args.price !== undefined ? args.price : (found ? priceOf(found) : null);
    const detail = args.detail !== undefined ? (args.detail.trim() || null) : (found?.detail ?? null);

    return {
      ok: true,
      resolved: { id: found?.id ?? null, name, unit, unitPrice, detail, old: null } satisfies Resolved,
      row: {
        icon: 'inventory_2',
        summary: `${found ? 'Save item' : 'Add item'} ${name}`,
        amount: unitPrice == null ? '' : priceText(unit, unitPrice),
        tone: 'neutral',
      },
    };
  },
  execute: async (ctx, resolved) => {
    const r = resolved as Resolved;
    const savedAt = new Date().toISOString();

    if (r.id === null) {
      // The name may have been saved in another tab since the card was drawn.
      const clash = (await products(ctx)).some(
        (row) => rowKey(row) === nameKeyOf(r.name) && row.saved_at && !row.deleted_at,
      );
      if (clash) return { ok: false, problem: `You already have an item named ${r.name}.` };

      const { error } = await ctx.db.insert('products', {
        user_id: ctx.userId,
        name: r.name,
        unit: r.unit,
        unit_price: r.unitPrice,
        detail: r.detail,
        saved_at: savedAt,
      });
      if (error) throw new Error(error.message);
      return { ok: true, result: { id: `saved-${nameKeyOf(r.name)}`, name: r.name } };
    }

    const { data, error } = await ctx.db.select<ProductRow>('products', {
      columns: '*',
      eq: { user_id: ctx.userId, id: r.id },
      limit: 1,
    });
    if (error) throw new Error(error.message);
    const row = data?.[0];
    if (!row) return { ok: false, problem: `That item is gone now.` };
    if (rowKey(row) !== nameKeyOf(r.name)) {
      return { ok: false, problem: `${r.name} changed since I looked. Ask me again.` };
    }
    if (
      r.old
      && (unitOf(row) !== r.old.unit
        || priceOf(row) !== r.old.unitPrice
        || (row.detail ?? null) !== r.old.detail)
    ) {
      return { ok: false, problem: `${r.name} changed since I looked. Ask me again.` };
    }

    const { error: updateError } = await ctx.db.update(
      'products',
      {
        unit: r.unit,
        unit_price: r.unitPrice,
        detail: r.detail,
        saved_at: savedAt,
        deleted_at: null,
      },
      { eq: { id: r.id } },
    );
    if (updateError) throw new Error(updateError.message);

    return { ok: true, result: { id: r.id, name: r.name } };
  },
  fallback: (result) => `Saved ${result.name}.`,
  fixture: {
    args: { name: 'Pressure wash', price: 250, unit: 'job' },
    result: { id: 'prod-9', name: 'Pressure wash' },
  },
  preview: {
    resolved: { id: null, name: 'Pressure wash', unit: 'job', unitPrice: 250, detail: null, old: null },
    row: {
      icon: 'inventory_2',
      summary: 'Add item Pressure wash',
      amount: '$250.00/job',
      tone: 'neutral',
    },
  },
});
